import React, { useState } from 'react';
import './App.css';
import Header from './components/Header';
import VoiceGuideBanner from './components/VoiceGuideBanner';
import SurvivorPortal from './components/SurvivorPortal';
import AdminDashboard from './components/AdminDashboard';

/**
 * Main application shell. Owns which portal is active (survivor vs admin)
 * and the global voice-guide toggle; everything else is delegated to the
 * portal components.
 */
export default function App() {
  const [portal, setPortal] = useState('survivor');
  const [voiceOn, setVoiceOn] = useState(false);
  const [voiceTranscript, setVoiceTranscript] = useState('');

  return (
    <div className="app-shell">
      <Header portal={portal} setPortal={setPortal} voiceOn={voiceOn} setVoiceOn={setVoiceOn} />

      {voiceOn && (
        <VoiceGuideBanner
          onDismiss={() => setVoiceOn(false)}
          onTranscript={setVoiceTranscript}
        />
      )}

      <main className="app-main">
        {portal === 'survivor' ? (
          <SurvivorPortal voiceTranscript={voiceTranscript} />
        ) : (
          <AdminDashboard />
        )}
      </main>

      <footer className="app-footer">
        SafeTrace — anonymous by design. No IP logging. No device fingerprinting.
      </footer>
    </div>
  );
}
